<script setup>import {ref,computed} from 'vue';import {Search} from 'lucide-vue-next';import AppShell from '../components/layout/AppShell.vue';import LeadTable from '../components/leads/LeadTable.vue';import {useAppStore} from '../stores/app';const store=useAppStore(),search=ref(''),status=ref('All'),channel=ref('All');const filtered=computed(()=>store.leads.filter(l=>(!search.value||`${l.name} ${l.id} ${l.interest}`.toLowerCase().includes(search.value.toLowerCase()))&&(status.value==='All'||l.status===status.value.toLowerCase())&&(channel.value==='All'||l.channel===channel.value)))</script>
<template><AppShell><div class="page"><div class="page-title"><div><h1>Leads</h1><p>Every inquiry, scored and tracked automatically.</p></div></div><div class="toolbar"><label><Search :size="16"/><input v-model="search" aria-label="Search leads" placeholder="Search leads, IDs or interests"/></label><select v-model="status" aria-label="Filter by status"><option v-for="s in ['All','New','Contacted','Qualified','Converted','Lost']">{{s}}</option></select><select v-model="channel" aria-label="Filter by channel"><option v-for="c in ['All','Telegram','WhatsApp','Web']">{{c}}</option></select></div><LeadTable :leads="filtered"/></div></AppShell></template>
<style scoped>.toolbar{display:flex;gap:9px;margin-bottom:16px}.toolbar label{max-width:360px;flex:1;display:flex;align-items:center;gap:8px;background:#fff;border:1px solid var(--border);border-radius:10px;padding-left:12px;color:var(--muted)}.toolbar label input{border:0}.toolbar select{width:150px}@media(max-width:600px){.toolbar{flex-wrap:wrap}.toolbar label{max-width:none;width:100%;flex-basis:100%}.toolbar select{flex:1}}</style>
